package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand/v2"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type Message struct {
	Type      string          `json:"type"`
	Message   json.RawMessage `json:"message,omitempty"`
}

type InitMessage struct {
	ID         int                  `json:"id"`
	NodeIDs    []int                 `json:"node_ids"`
	Topology   map[string][]string   `json:"topology"`
}

type BroadcastMessage struct {
	MessageID int       `json:"message_id"`
	Value     int        `json:"value"`
	Data      json.RawMessage `json:"data,omitempty"`
}

type ReadMessage struct {
	MessageID int `json:"msg_id"`
}

type TopologyMessage struct {
	Topo map[string][]string `json:"topology"`
}

func handleInit(ctx context.Context, node *maelstrom.Node, m maelstrom.Message) {
	var initMsg InitMessage
	if err := json.Unmarshal(m.Body, &initMsg); err != nil {
		log.Println("Error unmarshaling init:", err)
		return
	}

	node.Reply(m, map[string]any{"id": initMsg.ID})
}

func handleBroadcast(ctx context.Context, node *maelstrom.Node, m maelstrom.Message) {
	var msg BroadcastMessage
	if err := json.Unmarshal(m.Body, &msg); err != nil {
		log.Println("Error unmarshaling broadcast:", err)
		return
	}

	storeMutex.Lock()
	currentValues[msg.Value] = struct{}{}
	storeMutex.Unlock()

	node.Reply(m, "ok")

	// Start spreading this value to neighbors
	go spreadValue(ctx, node, msg.Value)
}

func handleRead(ctx context.Context, node *maelstrom.Node, m maelstrom.Message) {
	var msg ReadMessage
	if err := json.Unmarshal(m.Body, &msg); err != nil {
		log.Println("Error unmarshaling read:", err)
		return
	}

	storeMutex.Lock()
	values := make([]any, 0, len(currentValues))
	for val := range currentValues {
		values = append(values, val)
	}
	storeMutex.Unlock()

	node.RPC(m, node.ID, "read", map[string]any{
		"msg_id": msg.MessageID,
		"values": values,
	})
}

func handleTopology(ctx context.Context, node *maelstrom.Node, m maelstrom.Message) {
	var msg TopologyMessage
	if err := json.Unmarshal(m.Body, &msg); err != nil {
		log.Println("Error unmarshaling topology:", err)
		return
	}

	node.Reply(m, "ok")
}

type SpreadContext struct {
	ctx          context.Context
	nodeID       int
	value        int
	neighbors    map[int]bool // neighbors we can talk to
	rand         *rand.Rand
	nextTickTime time.Time
	mu           sync.Mutex
	sentTo       map[int]int   // neighbor -> times this node sent value (to avoid flooding)
}

func spreadValue(ctx context.Context, node *maelstrom.Node, value int) {
	spreadCtx := &SpreadContext{
		ctx:         ctx,
		nodeID:      node.ID,
		value:       value,
		neighbors:   nil, // will be populated from topology
		rand:        rand.New(rand.NewSource(int64(value))),
		nextTickTime: time.Now().Add(20 * time.Millisecond),
		sentTo:      make(map[int]int),
	}

	for {
		select {
		case <-ctx.Done():
			return
		case <-time.After(25 * time.Millisecond):
			spreadCtx.doSpread()
		}
	}
}

func (sc *SpreadContext) doSpread() {
	sc.mu.Lock()
	defer sc.mu.Unlock()

	if len(sc.neighbors) == 0 {
		return
	}

	// Each value should send to at least 1 neighbor per ~25ms
	// But we limit total messages. Let's send to 1-2 neighbors

	sendCount := sc.rand.IntN(3) // 0, 1, or 2 neighbors
	if sendCount == 0 {
		return
	}

	for i := 0; i < sendCount && len(sc.neighbors) > 0; i++ {
		neighborIDs := make([]int, 0, len(sc.neighbors))
		for nid := range sc.neighbors {
			neighborIDs = append(neighborIDs, nid)
		}

		if len(neighborIDs) == 0 {
			continue
		}

		idx := sc.rand.IntN(len(neighborIDs))
		neighborID := neighborIDs[idx]

		delete(sc.neighbors, neighborID)

		// Send the value to this neighbor
		msg := map[string]any{
			"type":      "spread",
			"value":     sc.value,
			"from_node": sc.nodeID,
			"to_node":   fmt.Sprintf("node%d", neighborID),
		}

		node.Send(node.ID, fmt.Sprintf("node%d", neighborID), "send_value", msg)

		// Track when we next send to avoid flooding
		sc.sentTo[neighborID] = time.Now().Add(20 * time.Millisecond).UnixMilli()
	}
}

func main() {
	node := maelstrom.NewNode()

	// Handle messages
	maelstrom.Handle(node, "init", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		handleInit(ctx, n, m)
	}, nil)

	maelstrom.Handle(node, "broadcast", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		handleBroadcast(ctx, n, m)
	}, nil)

	maelstrom.Handle(node, "read", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		handleRead(ctx, n, m)
	}, nil)

	maelstrom.Handle(node, "topology", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		handleTopology(ctx, n, m)
	}, nil)

	// Build the gossip node
	type GossipNode struct {
		id            int
		valueSet      map[int]struct{}
		neighbors     map[int]bool
		sentTo        map[int]int
		nextTickTime  time.Time
		mu            sync.Mutex
	}

	var (
		gossipNodes []*GossipNode
		topology    map[int][]int
	)

	maelstrom.Handle(node, "send_value", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var spreadMsg struct {
			Value     int `json:"value"`
			FromNode  int `json:"from_node"`
			ToNode    string `json:"to_node"`
		}

		if err := json.Unmarshal(m.Body, &spreadMsg); err != nil {
			log.Println("Error unmarshaling spread:", err)
			return
		}

		gossipMutex.Lock()
		nodeIdx := -1
		for i, gn := range gossipNodes {
			if gn.id == n.ID {
				nodeIdx = i
				break
			}
		}

		if nodeIdx == -1 {
			log.Println("GossipNode not found for", n.ID)
			gossipMutex.Unlock()
			return
		}

		syncValue := gossipNodes[nodeIdx]

		if err := json.Unmarshal(m.Body, &syncValue); err != nil {
			gossipMutex.Unlock()
			log.Println("Error unmarshaling sync:", err)
			return
		}

		gossipMutex.Unlock()
	}, maelstrom.MessageBody{})

	node.Run()
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand/v2"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type BroadcastMsg struct {
	MessageID int    `json:"message_id"`
	Value     int    `json:"value"`
	Data      string `json:"data"`
}

type TopologyMsg struct {
	Topo map[string][]string `json:"topology"`
}

type SendValueMsg struct {
	Value   int    `json:"value"`
	FromNode int  `json:"from_node"`
}

// Gossip node state
type gossipNode struct {
	mu         sync.RWMutex
	valueSet   map[int]struct{}
	neighbors  map[int]bool
	lastSendTo map[int]int // neighborID -> last sent timestamp (ms)
	nextTick   time.Time
	rand       *rand.Rand
}

var (
	allNodes []*gossipNode
	nodeMu   sync.Mutex
	topology map[int][]int
	initDone chan struct{}
)

func main() {
	ctx := context.Background()
	node := maelstrom.NewNode()

	// Handle init message - store node ID and topology
	maelstrom.Handle(node, "init", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			node.Reply(m, "error")
			return
		}

		// Store the topology info for this node
		nodeMu.Lock()
		initDone = make(chan struct{})
		topology = msg["topology"].(map[string][]string)
		allNodes = make([]*gossipNode, 0)
		nodeIdx := -1

		for i := range allNodes {
			if allNodes[i] != nil && allNodes[i].id == n.ID {
				nodeIdx = i
			}
		}

		newNode := &gossipNode{
			id:          n.ID,
			valueSet:    make(map[int]struct{}),
			neighbors:   make(map[int]bool),
			lastSendTo:  make(map[int]int),
			nextTick:    time.Now().Add(25 * time.Millisecond),
			rand:        rand.New(rand.NewSource(int64(n.ID))),
		}

		allNodes = append(allNodes, newNode)

		// Convert topology from string names to node IDs
		nodeIDs := make(map[string]int)
		for i, nID := range allNodes {
			if nID != nil && nID.id == n.ID {
				nodeIdx = i
			}
			nodeIDs["node"+fmt.Sprintf("%d", nID.id)] = nID.id
		}

		topo := msg["topology"].(map[string][]string)
		for _, gn := range allNodes {
			if gn != nil {
				var nodeNames []string
				for _, neighborName := range topo[fmt.Sprintf("node%d", gn.id)] {
					nodeID, ok := nodeIDs[neighborName]
					if ok {
						gn.neighbors[nodeID] = struct{}{}
						topology[gn.id] = append(topology[gn.id], nodeID)
					}
				}
			}
		}

		nodeMu.Unlock()

		node.Reply(m, "ok")
	}, maelstrom.MessageBody{})

	// Handle broadcast - store value and start spreading it
	maelstrom.Handle(node, "broadcast", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg BroadcastMsg
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			log.Println("Error unmarshaling broadcast:", err)
			node.Reply(m, "error")
			return
		}

		nodeMu.Lock()
		for _, gn := range allNodes {
			gn.mu.Lock()
			if gn.valueSet[msg.Value] == false {
				gn.valueSet[msg.Value] = struct{}{}
			}
			gn.mu.Unlock()
		}
		nodeMu.Unlock()

		node.Reply(m, "ok")

		// Start spreading this value
		go spreadValue(ctx, n, msg.Value)
	}, maelstrom.MessageBody{})

	// Handle read - return all values
	maelstrom.Handle(node, "read", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			log.Println("Error unmarshaling read:", err)
			node.Reply(m, "error")
			return
		}

		nodeMu.RLock()
		values := make([]int, 0, len(allNodes[0].valueSet))
		for _, gn := range allNodes {
			gn.mu.RLock()
			for val := range gn.valueSet {
				values = append(values, val)
			}
			gn.mu.RUnlock()
		}
		nodeMu.RUnlock()

		msg["values"] = values
		node.Reply(m, map[string]any{"type": "read_ok", "in_reply_to": msg["msg_id"], "messages": values})
	}, maelstrom.MessageBody{})

	// Handle send_value (from gossip protocol)
	maelstrom.Handle(node, "send_value", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var valMsg SendValueMsg
		if err := json.Unmarshal(m.Body, &valMsg); err != nil {
			log.Println("Error unmarshaling send_value:", err)
			return
		}

		nodeMu.Lock()
		for _, gn := range allNodes {
			gn.mu.Lock()
			if gn.valueSet[valMsg.Value] == false {
				gn.valueSet[valMsg.Value] = struct{}{}
			}
			gn.mu.Unlock()
		}
		nodeMu.Unlock()
	}, maelstrom.MessageBody{})

	node.Run()
}

func spreadValue(ctx context.Context, n *maelstrom.Node, value int) {
	for {
		select {
		case <-ctx.Done():
			return
		default:
			time.Sleep(25 * time.Millisecond)

			n.mu.RLock()
			neighbors := make([]int, 0, len(n.neighbors))
			now := time.Now().UnixMilli()
			for neighborID := range n.neighbors {
				if n.lastSendTo[neighborID] < now-20 {
					neighbors = append(neighbors, neighborID)
				}
			}
			n.mu.RUnlock()

			if len(neighbors) == 0 {
				continue
			}

			// Pick 1 random neighbor to send to
			idx := n.rand.IntN(len(neighbors))
			targetNeighbor := neighbors[idx]

			n.mu.Lock()
			delete(n.neighbors, targetNeighbor)
			n.lastSendTo[targetNeighbor] = now
			n.mu.Unlock()

			msgBody := map[string]any{
				"type":     "send_value",
				"value":    value,
				"from_node": n.id,
			}

			go maelstrom.RPC(n, fmt.Sprintf("node%d", targetNeighbor), "receive_value", msgBody)
		}
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand/v2"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node state for gossip protocol
type nodeState struct {
	id            int                    // Our node ID
	valueSet      map[int]struct{}       // Values we have
	neighbors     map[int]bool           // Neighbors to gossip with
	lastGossipTick time.Time             // When we last did full gossip
	nextGossip    time.Time             // Next gossip tick
	rand          *rand.Rand
	mu            sync.Mutex
}

var (
	allNodes      []*nodeState
	nodesByID     map[int]*nodeState
	initialized   chan struct{}
	topology      map[string][]int
)

func main() {
	ctx := context.Background()
	node := maelstrom.NewNode()

	// Handle init message
	maelstrom.Handle(node, "init", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var rawMsg map[string]any
		if err := json.Unmarshal(m.Body, &rawMsg); err != nil {
			node.Reply(m, "error")
			return
		}

		initDone := make(chan struct{})

		// Get topology and build our neighbor list
		topoRaw := rawMsg["topology"].(map[string][]string)

		// Extract node IDs from all nodes
		var allNodeIDs []int
		nodeIDMap := make(map[string]int) // "n1" -> 0, etc

		// Parse our own ID
		ourIDStr := ""
		idField := rawMsg["id"].(float64)

		// The init message has our id and node_ids list
		nodeIDsRaw := rawMsg["node_ids"].([]interface{})
		allNodeIDs = make([]int, len(nodeIDsRaw))
		for i, nidRaw := range nodeIDsRaw {
			allNodeIDs[i] = int(nidRaw.(float64))
			if allNodeIDs[i] == int(idField) {
				ourIDStr = fmt.Sprintf("node%d", allNodeIDs[i])
			}
		}

		// Build nodesByID map
		nodesByID = make(map[int]*nodeState)
		for _, nid := range allNodeIDs {
			ns := &nodeState{
				id:            nid,
				valueSet:      make(map[int]struct{}),
				lastGossipTick: time.Now().Add(100 * time.Millisecond), // Initial delay
				nextGossip:    time.Now().Add(50 * time.Millisecond),
				rand:          rand.New(rand.NewSource(int64(nid))),
			}
			nodesByID[nid] = ns
			ns.neighbors = make(map[int]bool)

			// Build neighbor map from topology
			if neighbors, ok := topoRaw[ourIDStr]; ok {
				for _, nbName := range neighbors {
					// Extract number from name like "n2" -> 2
					nbNum := parseNodeNum(nbName)
					if ns.id < nbNum { // Only add as neighbor if we're lower numbered (avoid cycles)
						ns.neighbors[nbNum] = true
					}
				}
			}

			// Add reverse edges for symmetric gossip
			for nid2, neighbors2 := range topoRaw {
				if ns.id != nid2 {
					ns2 := nodesByID[nid2]
					if ns2 != nil {
						var nbNums []int
						for _, nbName := range neighbors2 {
							nbNum := parseNodeNum(nbName)
							nbNums = append(nbNums, nbNum)
						}
						// Add this node as neighbor if not already
						if _, exists := ns.neighbors[nid2]; !exists {
							ns.neighbors[nid2] = true
						}
					}
				}
			}

			// Make sure we have at least 3 neighbors
			if len(ns.neighbors) < 3 && nid < allNodeIDs[18] { // Spread more if early nodes
				sortAndAddNeighbors(ns, topoRaw)
			}

			allNodes = append(allNodes, ns)
		}

		topology = topoRaw

		node.Reply(m, map[string]any{"id": idField})
	}, maelstrom.MessageBody{})

	// Handle broadcast
	maelstrom.Handle(node, "broadcast", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			node.Reply(m, "error")
			return
		}

		value := int(msg["value"].(float64))

		// Store value in this node's set
		n.mu.Lock()
		if n.valueSet == nil {
			n.valueSet = make(map[int]struct{})
		}
		n.valueSet[value] = struct{}{}
		n.mu.Unlock()

		node.Reply(m, "ok")

		// Start spreading immediately with exponential backoff-like behavior
		go func(val int) {
			for i := 0; i < 5; i++ { // Send to each neighbor up to 5 times per value lifecycle
				time.Sleep(30 * time.Millisecond)
				n.mu.Lock()
				if n.valueSet != nil && len(n.neighbors) > 0 {
					// Pick a random neighbor that we haven't sent to recently
					sendToRandomNeighbor(n, val)
				}
				n.mu.Unlock()
			}
		}(value)
	}, maelstrom.MessageBody{})

	// Handle read
	maelstrom.Handle(node, "read", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			node.Reply(m, "error")
			return
		}

		msgID := int(msg["msg_id"].(float64))

		n.mu.RLock()
		values := make([]int, 0, len(n.valueSet))
		for val := range n.valueSet {
			values = append(values, val)
		}
		n.mu.RUnlock()

		response := map[string]any{
			"type":           "read_ok",
			"in_reply_to":    msgID,
			"messages":       values,
		}
		node.Reply(m, response)
	}, maelstrom.MessageBody{})

	// Handle send_value (from gossip protocol from other nodes)
	maelstrom.Handle(node, "send_value", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var valMsg map[string]any
		if err := json.Unmarshal(m.Body, &valMsg); err != nil {
			log.Println("Error unmarshaling send_value:", err)
			return
		}

		value := int(valMsg["value"].(float64))

		n.mu.Lock()
		if n.valueSet == nil {
			n.valueSet = make(map[int]struct{})
		}
		n.valueSet[value] = struct{}{}
		n.mu.Unlock()

		// Reply back to sender so they know we received it (optional but good for RPC)
		node.Reply(m, "ok")

		// Gossip this value to our neighbors too
		go func() {
			time.Sleep(15 * time.Millisecond)
			for tick := 0; tick < 3; tick++ {
				time.Sleep(25 * time.Millisecond)
				n.mu.Lock()
				if n.valueSet != nil && len(n.neighbors) > 0 {
					sendToRandomNeighbor(n, value)
				}
				n.mu.Unlock()
			}
		}()
	}, maelstrom.MessageBody{})

	node.Run()
}

func parseNodeNum(name string) int {
	name = "node" + name[4:] // remove "node" prefix
	var num int
	for _, c := range name {
		if c >= '0' && c <= '9' {
			num = num*10 + int(c-'0')
		} else if c == '[' {
			break
		}
	}
	return num
}

func sortAndAddNeighbors(ns *nodeState, topoRaw map[string][]string) {
	// Sort and pick best neighbors to reach most of the network quickly
	var candidates []int
	for nid := range ns.neighbors {
		candidates = append(candidates, nid)
	}

	rng := rand.New(rand.NewSource(int64(ns.id)))
	sort.Slice(candidates, func(i, j int) bool {
		return rng.IntN(10) < 5
	})

	if len(candidates) > 3 {
		ns.neighbors = make(map[int]bool)
		for _, c := range candidates[:min(len(candidates), 8)] {
			ns.neighbors[c] = true
		}
	}
}

func sendToRandomNeighbor(ns *nodeState, value int) {
	if len(ns.neighbors) == 0 {
		return
	}

	// Pick a random neighbor to gossip with
	var target int
	maxIdx := -1
	for nid := range ns.neighbors {
		if maxIdx < 0 || ns.rand.IntN(3) < 2 { // 2/3 chance per neighbor
			target = nid
			maxIdx = len(ns.neighbors) - 1
		}
	}

	ns.mu.Lock()
	delete(ns.neighbors, target)
	ns.mu.Unlock()

	msgBody := map[string]any{
		"type":      "send_value",
		"value":     value,
		"from_node": ns.id,
	}

	if target < 0 && len(ns.neighbors) > 0 {
		for nid := range ns.neighbors {
			target = nid
			break
		}
	}

	if target >= 0 {
		go maelstrom.RPC(ns, fmt.Sprintf("node%d", target), "receive_value", msgBody)
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand/v2"
	"net"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// We need to track broadcast values and gossip them to neighbors
type state struct {
	id          int                  // This node's ID
	valueSet    map[int]struct{}     // Values we have seen
	neighbors   map[int]bool         // Our neighbors (we send to these and receive from)
	lastTick    time.Time            // When we last did a gossip tick
	nextTick    time.Time            // Next time we should gossip
	rand        *rand.Rand
	mu          sync.Mutex
}

var (
	initialized   chan struct{} = make(chan struct{})
	topologyMap   map[string][]int
)

func main() {
	node := maelstrom.NewNode()

	// Handle init message
	maelstrom.Handle(node, "init", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			node.Reply(m, "error")
			return
		}

		ourID := int(msg["id"].(float64))

		// Build state for this node
		ns := &state{
			id:        ourID,
			valueSet:  make(map[int]struct{}),
			lastTick:  time.Now(),
			nextTick:  time.Now().Add(15 * time.Millisecond),
			rand:      rand.New(rand.NewSource(int64(ourID))),
		}

		// Parse topology and build neighbor map
		topoRaw := msg["topology"].(map[string][]string)
		ns.neighbors = make(map[int]bool)

		neighborIDs := []int{}

		for neighborName, neighborList := range topoRaw {
			// Extract the numeric part from names like "n1"
			var nid int
			if len(neighborName) >= 4 && neighborName[:5] == "node" {
				suffix := neighborName[4:]
				var num int
				for _, c := range suffix {
					if c >= '0' && c <= '9' {
						num = num*10 + int(c-'0')
					} else if c == '[' {
						break
					}
				}
				nid = num
			} else if len(neighborName) > 0 {
				s := neighborName[1:] // skip leading quote-like char
				var num int
				for _, c := range s {
					if c >= '0' && c <= '9' {
						num = num*10 + int(c-'0')
					} else if c == '[' || c == ']' {
						break
					}
				}
				nid = num
			}

			if nid > ourID {
				ns.neighbors[nid] = true
				neighborIDs = append(neighborIDs, nid)
			}
		}

		// Also check if we should receive from others
		topologyMap = topoRaw

		node.Reply(m, "ok")
	}, maelstrom.MessageBody{})

	// Handle broadcast
	maelstrom.Handle(node, "broadcast", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			node.Reply(m, "error")
			return
		}

		value := int(msg["value"].(float64))

		ns.mu.Lock()
		if ns.valueSet == nil {
			ns.valueSet = make(map[int]struct{})
		}
		ns.valueSet[value] = struct{}{}
		ns.mu.Unlock()

		node.Reply(m, "ok")

		// Start spreading: gossip to all neighbors with some randomness
		go func(val int) {
			ticker := time.NewTicker(15 * time.Millisecond)
			defer ticker.Stop()

			for range ticker.C {
				ns.mu.Lock()
				if ns.valueSet == nil || len(ns.neighbors) == 0 || time.Now().After(ns.nextTick) {
					ns.nextTick = time.Now().Add(15 * time.Millisecond)
				} else {
					ns.nextTick = time.Now().Add(15 * time.Millisecond)
				}
				ns.mu.Unlock()

				gossipValue(n, val)
			}
		}(value)
	}, maelstrom.MessageBody{})

	// Handle read
	maelstrom.Handle(node, "read", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			node.Reply(m, "error")
			return
		}

		ns.mu.RLock()
		values := make([]int, 0, len(ns.valueSet))
		for val := range ns.valueSet {
			values = append(values, val)
		}
		ns.mu.RUnlock()

		response := map[string]any{
			"type":           "read_ok",
			"in_reply_to":    msg["msg_id"],
			"messages":       values,
		}
		node.Reply(m, response)
	}, maelstrom.MessageBody{})

	// Handle send_value (incoming gossip from neighbors)
	maelstrom.Handle(node, "send_value", func(ctx context.Context, n *maelstrom.Node, m maelstrom.Message) {
		var msg map[string]any
		if err := json.Unmarshal(m.Body, &msg); err != nil {
			log.Println("Error unmarshaling send_value:", err)
			return
		}

		value := int(msg["value"].(float64))

		ns.mu.Lock()
		if ns.valueSet == nil {
			ns.valueSet = make(map[int]struct{})
		}
		ns.valueSet[value] = struct{}{}
		ns.mu.Unlock()

		// Reply back to the sender
		node.Reply(m, "ok")

		// Gossip this value too
		go func(val int) {
			ticker := time.NewTicker(15 * time.Millisecond)
			defer ticker.Stop()

			for range ticker.C {
				ns.mu.Lock()
				if ns.valueSet != nil && len(ns.neighbors) > 0 && time.Now().After(ns.nextTick) {
					ns.nextTick = time.Now().Add(15 * time.Millisecond)
				} else if time.Now().Before(ns.nextTick) {
					ns.mu.Unlock()
					continue
				}
				ns.mu.Unlock()

				gossipValue(n, val)
			}
		}(value)
	}, maelstrom.MessageBody{})

	node.Run()
}

func gossipValue(n *maelstrom.Node, value int) {
	if n == nil {
		return
	}

	n.mu.Lock()
	neighborList := make([]int, 0, len(n.neighbors))
	for nid := range n.neighbors {
		neighborList = append(neighborList, nid)
	}

	// Each node should send to about 2-3 neighbors per cycle max
	sendCount := 1 
	if n.rand.IntN(3) == 0 || n.rand.IntN(4) == 0 { // ~75% chance to send at least once
		if sendCount < 2 && n.rand.IntN(2) == 0 {
			sendCount = 2
		}
	}

	n.mu.Unlock()

	for i := 0; i < sendCount; i++ {
		var targetID int
		maxIdx := -1

		if len(neighborList) > 0 {
			targetIdx := n.rand.IntN(len(neighborList))
			targetID = neighborList[targetIdx]

			n.mu.Lock()
			delete(n.neighbors, targetID)
			n.mu.Unlock()
		}

		msgBody := map[string]any{
			"type":      "send_value",
			"value":     value,
			"from_node": n.id,
		}

		go maelstrom.RPC(n, fmt.Sprintf("node%d", targetID), "receive_value", msgBody)
	}
}
